let feedRequest=null;
async function connectFeeds({background=false}={}){if(feedRequest)return feedRequest;if(!state.rows.length&&!background)setSourceStatus("connecting");feedRequest=(async()=>{const load=async kind=>{const response=await fetch(`/api/tenders?kind=${kind}`,{headers:{Accept:"application/json"},signal:AbortSignal.timeout(50000)});if(!response.ok)throw new Error(`${kind} feed proxy HTTP ${response.status}`);const payload=await response.json();return unwrap(payload.data??payload[kind]).map(r=>normalizeRecord(r,kind==="active"?"live":"archived")).filter(Boolean);};try{const active=await load("active");if(!active.length)throw new Error("The active public feed returned no usable notices.");state.rows=active;state.source="live";state.lastSynced=new Date();setSourceStatus("connected",`${active.length.toLocaleString()} active notices`);renderAll();load("archived").then(archived=>{if(archived.length){state.rows=[...active,...archived];state.lastSynced=new Date();setSourceStatus("connected",`${state.rows.length.toLocaleString()} notices loaded`);renderAll();}}).catch(()=>{});}catch(error){if(!state.rows.length){state.source="unavailable";setSourceStatus("unavailable",`Could not load the public e-GP data feed (${error.message}). No sample data is shown.`);renderAll();}else{setSourceStatus("connected",`${state.rows.length.toLocaleString()} cached notices · refresh failed`);}}finally{feedRequest=null;}})();return feedRequest;}
function setSourceStatus(status,message=""){
 const pill=$(".snapshot-pill");
 pill.className=`snapshot-pill ${status}`;
 pill.innerHTML=`<i></i>${status==="connected"?"Live source connected":status==="connecting"?"Connecting to e-GP feed…":"Feed unavailable"}`;
 const callout=$(".preview-callout");
 if(status==="connected")callout.innerHTML=`<span class="callout-icon success">✓</span><span><b>Public feed connected</b> ${escapeHtml(message)} · Verify deadline and eligibility on the official notice.</span><a href="https://eprocure.gov.bd/" target="_blank" rel="noreferrer">Open e-GP ↗</a>`;
 else if(status==="unavailable")callout.innerHTML=`<span class="callout-icon">!</span><span><b>Feed unavailable</b> ${escapeHtml(message)}</span><button class="callout-action" id="retry-feed">Retry ↻</button>`;
 else callout.innerHTML=`<span class="callout-icon">◷</span><span><b>Connecting to the public feed</b> Loading current notices from e-GP mirror storage…</span>`;
 $("#retry-feed")?.addEventListener("click",connectFeeds);
 const insightCallout=$(".insights-heading ~ .preview-callout")[0];
 if(insightCallout&&status==="connected")insightCallout.innerHTML=`<span class="callout-icon success">✓</span><span><b>Public feed connected</b> Analytics are based on the notices currently loaded.</span>`;
 else if(insightCallout&&status==="unavailable")insightCallout.innerHTML=`<span class="callout-icon">!</span><span><b>Feed unavailable</b> Connect to the public feed before using these insights.</span><button class="callout-action" id="insight-retry">Retry ↻</button>`;
 $("#insight-retry")?.addEventListener("click",connectFeeds);
}function escapeHtml(s){return String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"}[c]));}
function formatBDT(v,short=true){if(!v)return "—";if(short){if(v>=1e7)return `৳${(v/1e7).toLocaleString("en-BD",{maximumFractionDigits:2})} Cr`;if(v>=1e5)return `৳${(v/1e5).toLocaleString("en-BD",{maximumFractionDigits:2})} L`;}return `৳${Math.round(v).toLocaleString("en-BD")}`;}
function parseFeedDate(v){if(!v||v==="—")return null;if(v instanceof Date)return v;const s=String(v).trim(),m=s.match(/^(\d{1,2})[- ]([A-Za-z]{3})[- ](\d{4})(?:[ T]+(\d{1,2}):(\d{2})(?:\s*(AM|PM))?)?$/i);if(m){const months={jan:0,feb:1,mar:2,apr:3,may:4,jun:5,jul:6,aug:7,sep:8,oct:9,nov:10,dec:11};let hour=Number(m[4]||0);if(m[6])hour=hour%12+(m[6].toUpperCase()==="PM"?12:0);return new Date(Number(m[3]),months[m[2].toLowerCase()],Number(m[1]),hour,Number(m[5]||0));}const d=new Date(s);return Number.isNaN(+d)?null:d;}
function fmtDate(v){const d=parseFeedDate(v);return d?new Intl.DateTimeFormat("en-GB",{day:"2-digit",month:"short",year:"numeric"}).format(d):String(v||"—");}
function fmtDateTime(v){const d=parseFeedDate(v);return d?new Intl.DateTimeFormat("en-GB",{day:"2-digit",month:"short",year:"numeric",hour:"2-digit",minute:"2-digit",hourCycle:"h23"}).format(d):String(v||"—");}
function daysLeft(v){const d=parseFeedDate(v);return d?Math.ceil((d-new Date())/86400000):null;}
function timeRemaining(v){const d=parseFeedDate(v);if(!d)return "Deadline not listed";let mins=Math.floor((d-new Date())/60000);if(mins<0)return "Deadline passed";const days=Math.floor(mins/1440);mins%=1440;const hours=Math.floor(mins/60);mins%=60;return `${days}d ${String(hours).padStart(2,"0")}h ${String(mins).padStart(2,"0")}m`;}
function statusRows(status=state.status){let list=state.rows.filter(r=>status==="all"||r.status===status);const q=$("#search-input").value.trim().toLowerCase();if(q)list=list.filter(r=>[r.id,r.title,r.org,r.pe,r.district,r.nature,r.method].join(" ").toLowerCase().includes(q));const f={nature:$("#filter-nature").value,method:$("#filter-method").value,district:$("#filter-district").value,org:$("#filter-org").value,pe:$("#filter-pe").value};if(f.nature)list=list.filter(r=>r.nature.toLowerCase().includes(f.nature.toLowerCase()));if(f.method)list=list.filter(r=>r.method===f.method);if(f.district)list=list.filter(r=>r.district===f.district);if(f.org)list=list.filter(r=>r.org===f.org);if(f.pe)list=list.filter(r=>r.pe===f.pe);const sort=$("#sort-select").value;list.sort((a,b)=>sort==="budget"?b.budget-a.budget:sort==="newest"?(parseFeedDate(b.published)?.getTime()||0)-(parseFeedDate(a.published)?.getTime()||0):(daysLeft(a.deadline)??99999)-(daysLeft(b.deadline)??99999));return list;}
