function pageNumbers(cur,max){if(max<=5)return Array.from({length:max},(_,i)=>i+1);const nums=[1,cur-1,cur,cur+1,max].filter((x,i,a)=>x>=1&&x<=max&&a.indexOf(x)===i).sort((a,b)=>a-b);const out=[];nums.forEach((n,i)=>{if(i&&n-nums[i-1]>1)out.push("…");out.push(n);});return out;}
function fillOptions(id,values,label){const el=$(id),current=el.value;el.innerHTML=`<option value="">${label}</option>`+[...new Set(values.filter(Boolean))].sort((a,b)=>a.localeCompare(b)).map(v=>`<option value="${escapeHtml(v)}">${escapeHtml(v)}</option>`).join("");if([...el.options].some(o=>o.value===current))el.value=current;}
function renderFilterOptions(){fillOptions("#filter-nature",state.rows.map(r=>r.nature),"All natures");fillOptions("#filter-method",state.rows.map(r=>r.method),"All methods");fillOptions("#filter-district",state.rows.map(r=>r.district),"All districts");fillOptions("#filter-org",state.rows.map(r=>r.org),"All organizations");fillOptions("#filter-pe",state.rows.map(r=>r.pe),"All entities");fillOptions("#insight-district",state.rows.map(r=>r.district),"All districts");}
