function toast(text){const el=$("#toast");el.textContent=text;el.classList.add("show");clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove("show"),2200);}
async function copyId(id){try{await navigator.clipboard.writeText(id);toast(`Tender ID ${id} copied`);}catch{toast(`Tender ID: ${id}`);}}
function setSaved(id){if(state.saved.has(id))state.saved.delete(id);else state.saved.add(id);localStorage.setItem("tenderdesk-saved",JSON.stringify([...state.saved]));renderRows();renderSaved();$("#saved-count").textContent=state.saved.size;}
function showDetail(id){const r=state.rows.find(x=>x.id===id);if(!r)return;const days=daysLeft(r.deadline);$("#modal-content").innerHTML=`<div class="modal-eyebrow">${escapeHtml(r.status==="live"?"LIVE OPPORTUNITY":"ARCHIVED NOTICE")} · ${escapeHtml(r.method)} · ${escapeHtml(r.nature)}</div><h2 id="modal-title">${escapeHtml(r.title)}</h2><div class="modal-org">${escapeHtml(r.org)} <span>·</span> ${escapeHtml(r.district)}</div><div class="modal-id">TENDER ID <b>${escapeHtml(r.id)}</b><button data-copy="${escapeHtml(r.id)}">Copy ID</button></div><div class="modal-grid"><div><small>PROCURING ENTITY</small><b>${escapeHtml(r.pe)}</b></div><div><small>ESTIMATED BUDGET</small><b>${formatBDT(r.budget,false)}</b></div><div><small>TENDER DOCUMENT FEE</small><b>${formatBDT(r.fee,false)}</b></div><div><small>TENDER SECURITY</small><b>${formatBDT(r.security,false)}</b></div><div><small>PUBLISHED</small><b>${fmtDate(r.published)}</b></div><div><small>${days!==null&&days<0?"CLOSED":"CLOSING"}</small><b>${fmtDate(r.deadline)}${days!==null&&days>=0?` · ${days} days`:""}</b></div></div><div class="eligibility-box"><span>ELIGIBILITY REQUIREMENTS</span><b>${escapeHtml(r.eligibility)}</b><small>Confirm complete requirements in the official tender document.</small></div><div class="modal-actions"><button class="save-modal" data-save="${escapeHtml(id)}">${state.saved.has(id)?"♥ Saved":"♡ Save notice"}</button><a href="${escapeHtml(r.url||`https://www.eprocure.gov.bd/resources/common/ViewTender.jsp?id=${r.id}`)}" target="_blank" rel="noreferrer">Open official e-GP notice ↗</a></div>`;$("#modal").hidden=false;document.body.classList.add("modal-open");}
function renderSaved(){const rows=state.rows.filter(x=>state.saved.has(x.id));$("#saved-total").textContent=rows.length;$("#saved-count").textContent=rows.length;$("#saved-list").innerHTML=rows.length?rows.map(r=>`<div class="saved-row"><button class="notice-title" data-detail="${escapeHtml(r.id)}">${escapeHtml(r.title)}</button><span>${escapeHtml(r.org)} · ${escapeHtml(r.district)}</span><b>${formatBDT(r.budget)}</b><button class="save-button saved" data-save="${escapeHtml(r.id)}" aria-label="Remove saved tender">♥</button></div>`).join(""):`<div class="saved-empty"><span>♡</span><b>No saved notices yet</b><p>Save a tender from the opportunity feed and it will appear here.</p><button data-go="feed">Browse opportunities →</button></div>`;}
function insightRows(){let list=state.rows;const district=$("#insight-district").value,nature=$("#insight-nature").value;if(district)list=list.filter(x=>x.district===district);if(nature)list=list.filter(x=>x.nature.toLowerCase().includes(nature.toLowerCase()));const q=$("#insight-search").value.trim().toLowerCase();if(q)list=list.filter(x=>[x.id,x.title,x.org,x.pe].join(" ").toLowerCase().includes(q));return list;}
function renderInsights(){const rows=insightRows(),sum=rows.reduce((n,x)=>n+x.budget,0),avg=rows.length?sum/rows.length:0,big=[...rows].sort((a,b)=>b.budget-a.budget)[0];$("#insight-budget").textContent=formatBDT(sum);$("#insight-count").textContent=rows.length;$("#insight-average").textContent=formatBDT(avg);$("#insight-largest").textContent=formatBDT(big?.budget||0);$("#insight-largest-name").textContent=big?big.org:"No matching notices";const orgs={};for(const r of rows)orgs[r.org]=(orgs[r.org]||0)+(state.metric==="budget"?r.budget:1);const top=Object.entries(orgs).sort((a,b)=>b[1]-a[1]).slice(0,6),max=top[0]?.[1]||1;$("#org-chart").innerHTML=top.map(([name,val],i)=>`<div class="org-bar-row"><span class="org-label" title="${escapeHtml(name)}">${escapeHtml(name)}</span><div class="bar-track"><i style="width:${Math.max(4,val/max*100)}%;--bar-index:${i}"></i></div><b>${state.metric==="budget"?formatBDT(val):val}</b></div>`).join("")||`<div class="chart-no-data">No notices are available from the feed yet.</div>`;const types=["Works","Goods","Services"].map(n=>({name:n,items:rows.filter(r=>r.nature.toLowerCase().includes(n.toLowerCase()))}));const colors=["#27775d","#89ac6b","#d6a46d"],all=rows.length||1;$("#nature-chart").innerHTML=`<div class="donut-wrap"><div class="donut" style="--p1:${types[0].items.length/all*100}%;--p2:${(types[0].items.length+types[1].items.length)/all*100}%"><div><b>${rows.length}</b><small>notices</small></div></div></div><div class="nature-legend">${types.map((t,i)=>`<div><i style="background:${colors[i]}"></i><span>${t.name}</span><b>${t.items.length}</b><small>${Math.round(t.items.length/all*100)}%</small></div>`).join("")}</div>`;$("#insight-rows").innerHTML=[...rows].sort((a,b)=>b.budget-a.budget).slice(0,6).map(r=>`<tr><td><button class="mini-id" data-detail="${escapeHtml(r.id)}">${escapeHtml(r.id)}</button></td><td>${escapeHtml(r.org)}</td><td class="insight-package">${escapeHtml(r.title)}</td><td>${escapeHtml(r.district)}</td><td><span class="nature-tag ${chipForNature(r.nature)}">${escapeHtml(r.nature.split(" ·")[0].toUpperCase())}</span></td><td><b>${formatBDT(r.budget)}</b></td></tr>`).join("");}
function renderTrend(rows=insightRows()){
  const byMonth=new Map();
  for(const row of rows){const d=new Date(row.published);if(Number.isNaN(+d))continue;const key=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}`;byMonth.set(key,(byMonth.get(key)||0)+(state.metric==="budget"?row.budget:1));}
  const months=[...byMonth.keys()].sort();
  if(months.length<3){$("#trend-chart").innerHTML=`<div class="chart-no-data">At least three months of published notice history are needed to calculate a trend.</div>`;return;}
  const actualMonths=months.slice(-8),values=actualMonths.map(m=>byMonth.get(m)||0),n=values.length;
  const meanX=(n-1)/2,meanY=values.reduce((a,b)=>a+b,0)/n;
  const slope=values.reduce((a,y,x)=>a+(x-meanX)*(y-meanY),0)/(values.reduce((a,_,x)=>a+(x-meanX)**2,0)||1);
  const forecast=Array.from({length:4},(_,i)=>Math.max(0,meanY+slope*(n+i-meanX)));
  const series=[...values,...forecast],W=720,H=206,L=58,R=16,T=12,B=34,CW=W-L-R,CH=H-T-B,max=Math.max(...series,1)*1.15;
  const xy=(v,i)=>[L+(CW/(series.length-1))*i,T+CH-(v/max)*CH];
  const path=arr=>arr.map((v,i)=>{const [x,y]=xy(v,i);return `${i?"L":"M"}${x.toFixed(1)} ${y.toFixed(1)}`;}).join(" ");
  const projected=[values.at(-1),...forecast],actualPath=path(values),projectionPath=projected.map((v,i)=>{const [x,y]=xy(v,n-1+i);return `${i?"L":"M"}${x.toFixed(1)} ${y.toFixed(1)}`;}).join(" ");
  const allMonthKeys=[...actualMonths];let date=new Date(`${actualMonths.at(-1)}-01T00:00:00`);for(let i=0;i<4;i++){date=new Date(date.getFullYear(),date.getMonth()+1,1);allMonthKeys.push(`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,"0")}`);}
  const label=m=>{const [y,mo]=m.split("-").map(Number);return `${new Date(y,mo-1,1).toLocaleString("en",{month:"short"})} '${String(y).slice(-2)}`;};
  const grid=[0,1,2,3].map(i=>{const value=max*i/3,y=T+CH-(value/max)*CH;return `<line x1="${L}" y1="${y}" x2="${W-R}" y2="${y}" class="trend-gridline"/><text x="${L-9}" y="${y+3}" text-anchor="end" class="trend-axis-label">${state.metric==="budget"?formatBDT(value):Math.round(value)}</text>`;}).join("");
  const labels=allMonthKeys.map((m,i)=>{if(allMonthKeys.length>9&&i%2===1&&i!==allMonthKeys.length-1)return "";const [x]=xy(0,i);return `<text x="${x}" y="${H-8}" text-anchor="middle" class="trend-axis-label">${label(m)}</text>`;}).join("");
  const dots=values.map((v,i)=>{const [x,y]=xy(v,i);return `<circle cx="${x}" cy="${y}" r="3.5" class="trend-dot"/>`;}).join("");
  $("#trend-chart").innerHTML=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Historical publication trend and four month linear projection">${grid}<path d="${actualPath}" class="trend-actual"/><path d="${projectionPath}" class="trend-projection"/>${dots}${labels}</svg>`;
}
const baseRenderInsights=renderInsights;renderInsights=function(){baseRenderInsights();renderTrend(insightRows());};function navigate(page){$$(".page").forEach(x=>{x.hidden=x.id!==`${page}-page`;x.classList.toggle("active-page",x.id===`${page}-page`);});$$(".nav-item").forEach(x=>x.classList.toggle("active",x.dataset.page===page));$("#crumb-title").textContent=page==="feed"?"Opportunity feed":page==="insights"?"Market insights":page==="saved"?"Saved tenders":"Contract awards";$("#sidebar").classList.remove("open");if(page==="insights")renderInsights();if(page==="saved")renderSaved();if(page==="awards"&&!state.awards.loaded)fetchAwards();window.location.hash=page;}

document.addEventListener("click",e=>{const nav=e.target.closest(".nav-item,[data-go]");if(nav){e.preventDefault();navigate(nav.dataset.page||nav.dataset.go);return;}const status=e.target.closest("[data-status]");if(status){state.status=status.dataset.status;state.page=1;$$(".status-tab").forEach(x=>x.classList.toggle("active",x===status));renderRows();return;}const pager=e.target.closest(".page-btn[data-page]");if(pager){pageTo(Number(pager.dataset.page));return;}const save=e.target.closest("[data-save]");if(save){e.stopPropagation();setSaved(save.dataset.save);return;}const detail=e.target.closest("[data-detail]");if(detail){showDetail(detail.dataset.detail);return;}const copy=e.target.closest("[data-copy]");if(copy){copyId(copy.dataset.copy);return;}const metric=e.target.closest("[data-metric]");if(metric){state.metric=metric.dataset.metric;$$(".metric-btn").forEach(x=>x.classList.toggle("active",x===metric));renderInsights();return;}if(e.target.id==="clear-filters"||e.target.id==="empty-reset"){$("#search-input").value="";["#filter-nature","#filter-method","#filter-district","#filter-org","#filter-pe"].forEach(x=>$(x).value="");state.status="live";state.page=1;$$(".status-tab").forEach(x=>x.classList.toggle("active",x.dataset.status==="live"));renderRows();return;}if(e.target.id==="modal-close"||e.target.id==="modal"){ $("#modal").hidden=true;document.body.classList.remove("modal-open");}if(e.target.id==="menu-toggle")$("#sidebar").classList.toggle("open");});
$("#feed-refresh").addEventListener("click",connectFeeds);
$("#search-input").addEventListener("input",()=>{state.page=1;const q=$("#search-input").value.trim();$("#search-hint").textContent=/^\d{5,}$/.test(q)?"Matching by tender ID":"Search all notices";renderRows();});
$("#search-input").addEventListener("keydown",e=>{if(e.key==="Enter"){const row=statusRows()[0];if(/^\d+$/.test(e.currentTarget.value.trim())&&row)showDetail(row.id);}});
["#filter-nature","#filter-method","#filter-district","#filter-org","#filter-pe","#sort-select"].forEach(sel=>$(sel).addEventListener("change",()=>{state.page=1;renderRows();}));
["#insight-district","#insight-nature"].forEach(sel=>$(sel).addEventListener("change",renderInsights));$("#insight-search").addEventListener("input",renderInsights);
$("#modal").addEventListener("keydown",e=>{if(e.key==="Escape"){$("#modal").hidden=true;document.body.classList.remove("modal-open");}});
document.addEventListener("keydown",e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==="k"){e.preventDefault();navigate("feed");$("#search-input").focus();}if(e.key==="Escape"&&!$("#modal").hidden){$("#modal").hidden=true;document.body.classList.remove("modal-open");}});
$("#menu-toggle").addEventListener("click",()=>$("#sidebar").classList.toggle("open"));
$("#local-date").textContent=new Intl.DateTimeFormat("en-BD",{weekday:"long",day:"numeric",month:"long",timeZone:"Asia/Dhaka"}).format(new Date());
const startPage=location.hash.replace("#","");if(["feed","insights","saved","awards"].includes(startPage))navigate(startPage);renderAll();connectFeeds();setInterval(()=>{if(document.visibilityState==="visible")connectFeeds({background:true});},10*60*1000);

function fillAwardSelect(id,options,firstLabel){const select=$(id),selected=select.value;select.innerHTML=`<option value="0">${firstLabel}</option>`+(options||[]).map(o=>`<option value="${escapeHtml(o.value)}">${escapeHtml(o.label)}</option>`).join("");if([...select.options].some(o=>o.value===selected))select.value=selected;}
function renderAwards(){const a=state.awards,query=$("#award-search").value.trim().toLowerCase();const records=a.records.filter(r=>!query||[r.ministry,r.agency,r.reference,r.title,r.procuringEntity,r.procurementType,r.district,r.awardDate,r.supplier,r.supplierAddress,r.contractValue].join(" ").toLowerCase().includes(query));$("#award-total").textContent=Number(a.total||0).toLocaleString();$("#award-nav-count").textContent=Number(a.total||0).toLocaleString();$("#award-page-number").textContent=String(a.page);$("#award-updated").textContent=a.fetchedAt?`Updated ${new Intl.DateTimeFormat("en-GB",{day:"2-digit",month:"short",hour:"2-digit",minute:"2-digit",timeZone:"Asia/Dhaka"}).format(new Date(a.fetchedAt))} BST`:a.loading?"Connecting to BPPA…":"—";$("#award-rows").innerHTML=records.map(r=>`<tr><td class="award-description"><b>${escapeHtml(r.ministry)}${r.agency?` · ${escapeHtml(r.agency)}`:""}</b><span class="award-reference">${escapeHtml(r.reference)}</span><strong>${escapeHtml(r.title)}</strong><small>Advertised ${escapeHtml(r.advertisementDate||"—")}</small></td><td class="award-entity"><span>${escapeHtml(r.procuringEntity)}</span><small>${escapeHtml(r.procurementType)}</small></td><td>${escapeHtml(r.district)}</td><td class="award-supplier"><b>${escapeHtml(r.supplier)}</b><small>${escapeHtml(r.supplierAddress)}</small></td><td class="award-value">${escapeHtml(r.contractValue)}</td><td>${escapeHtml(r.awardDate)}</td><td><a class="row-open" href="${escapeHtml(r.detailUrl)}" target="_blank" rel="noreferrer" aria-label="Open BPPA award detail">↗</a></td></tr>`).join("");$("#award-empty").hidden=records.length!==0||a.loading||!a.loaded;$("#award-range").textContent=a.loaded?(query?`${records.length} matches on this page · showing ${a.pageSize} official records per page`:a.total?`Showing ${(a.page-1)*a.pageSize+1}–${Math.min(a.page*a.pageSize,a.total)} of ${Number(a.total).toLocaleString()} official awards`:"No official awards match these filters"):"Loading official results…";$("#award-prev").disabled=a.loading||a.page<=1;$("#award-next").disabled=a.loading||a.page*a.pageSize>=a.total;}
async function fetchAwards(){const a=state.awards;if(a.loading){a.queued=true;return;}a.loading=true;$("#award-error").hidden=true;$("#award-status").innerHTML='<span class="callout-icon">◷</span><span><b>Connecting to BPPA</b> Loading published contract awards…</span>';renderAwards();const params=new URLSearchParams({page:String(a.page-1)});for(const [id,key] of [["#award-nature","procurementTypeId.id"],["#award-ministry","ministryId.id"],["#award-method","procurementMethodId.id"],["#award-view-by","viewResultBy"]]){const value=$(id).value;if(value&&value!=="0")params.set(key,value);}try{const response=await fetch(`/api/contract-awards?${params}`,{headers:{Accept:"application/json"},cache:"no-store",signal:AbortSignal.timeout(25000)});if(!response.ok)throw new Error(`BPPA request failed (${response.status})`);const payload=await response.json();a.records=Array.isArray(payload.records)?payload.records:[];a.total=Number(payload.total)||0;a.pageSize=Number(payload.pageSize)||10;a.fetchedAt=payload.fetchedAt;a.loaded=true;a.filters=payload.filters||a.filters;if(a.filters){fillAwardSelect("#award-nature",a.filters.natures,"All natures");fillAwardSelect("#award-ministry",a.filters.ministries,"All ministries");fillAwardSelect("#award-method",a.filters.methods,"All types");}$("#award-status").innerHTML=`<span class="callout-icon success">✓</span><span><b>BPPA register connected</b> ${a.total.toLocaleString()} public contract awards · Source page refreshes from BPPA when requested.</span><a href="https://bppa.gov.bd/contract-award/contract-award-list.html" target="_blank" rel="noreferrer">Open BPPA ↗</a>`;$("#award-error").hidden=true;}catch(error){a.records=[];a.total=0;a.loaded=false;$("#award-error-message").textContent="The official BPPA award list is temporarily unavailable. Please try again shortly.";$("#award-error").hidden=false;$("#award-status").innerHTML='<span class="callout-icon">!</span><span><b>BPPA is unavailable</b> No example records are shown.</span>';}finally{a.loading=false;renderAwards();if(a.queued){a.queued=false;fetchAwards();}}}
$("#award-refresh").addEventListener("click",fetchAwards);$("#award-retry").addEventListener("click",fetchAwards);$("#award-prev").addEventListener("click",()=>{if(state.awards.page>1){state.awards.page--;fetchAwards();}});$("#award-next").addEventListener("click",()=>{if(state.awards.page*state.awards.pageSize<state.awards.total){state.awards.page++;fetchAwards();}});$("#award-search").addEventListener("input",renderAwards);["#award-nature","#award-ministry","#award-method","#award-view-by"].forEach(id=>$(id).addEventListener("change",()=>{state.awards.page=1;fetchAwards();}));$("#award-reset").addEventListener("click",()=>{$("#award-search").value="";$("#award-nature").value="0";$("#award-ministry").value="0";$("#award-method").value="0";$("#award-view-by").value="awardNotificationDate";state.awards.page=1;fetchAwards();});
